// ── source: vcx/platform/journal_detached_payload_test.v ──
// journal_detached_payload_test.v — I1 row 11 (#720 / erasure L184, audit
// C1): DETACHED-PAYLOAD entries. The entry-canonical preimage carries the
// payload's own Tier-1 tagged ADDRESS as an envelope field (ONE entry
// form, no dual-accept); the payload is stored as its own doc. The
// mandate under test: `verify`'s three checks all pass with payloads
// DESTROYED — the chain covers the address, which is intact — and a
// shredded entry reads event-less (absence; the typed [erased] tombstone
// is the additive post-I1 read).

fn jdp_append(j cx.Node, event string) cx.Node {
	ev := cx.parse(event) or { panic('parse event') }.elements[0]
	attribution := cx.Element{
		name:  code.map_marker_name
		items: [
			cx.Node(cx.Element{
				name:  'actor'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('did:key:test')
					data_type: cx.ScalarType.string_type
				})]
			}),
			cx.Node(cx.Element{
				name:  'authority'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('test:suite')
					data_type: cx.ScalarType.string_type
				})]
			}),
		]
	}
	r := journal_stdlib_builtin('journal-append', [j, cx.Node(ev), cx.Node(attribution)]) or {
		panic('append: ${err.msg()}')
	}
	assert !is_err_value(r), 'append must succeed: ${render_canonical(r)}'
	return r
}

fn jdp_verify_valid(j cx.Node) bool {
	r := journal_stdlib_builtin('journal-verify', [j]) or { panic('verify: ${err.msg()}') }
	if r is cx.Element {
		return jrn_entry_attr(r, 'valid') == 'true'
	}
	return false
}

fn jdp_read(j cx.Node, seq int) cx.Element {
	r := journal_stdlib_builtin('journal-read', [j, cx.Node(cx.ScalarNode{
		value:     cx.ScalarValue(i64(seq))
		data_type: cx.ScalarType.int_type
	})]) or { panic('read: ${err.msg()}') }
	if r is cx.Element {
		return r
	}
	panic('read did not return an element')
}

// journal_shred_payload_for_test deletes a payload doc by address through
// the store's own delete verb — the minimal stand-in for the post-I1
// shred machinery (this row ships the FORM; the verbs are additive).
fn journal_shred_payload_for_test(j cx.Node, addr string) bool {
	mut jj, _, ok := jrn_get_open(j)
	if !ok {
		return false
	}
	r := store_stdlib_builtin('store-delete-doc', [jrn_store_handle(jj.store_id),
		cx.Node(cx.ScalarNode{
			value:     cx.ScalarValue(addr)
			data_type: cx.ScalarType.string_type
		})]) or { return false }
	return !is_err_value(r)
}

fn test_verify_green_with_payloads_gone() {
	caps_set_all()
	j := journal_stdlib_builtin('journal-open', [store_str('mem://jdp-1'), store_str('acme')]) or {
		panic('open')
	}
	jdp_append(j, '[order [total 5]]')
	jdp_append(j, '[order [total 7]]')
	jdp_append(j, '[order [total 9]]')
	assert jdp_verify_valid(j), 'chain must verify before the shred'

	// Every entry carries the payload ADDRESS (the envelope field) and
	// reads back HYDRATED (the [event] child re-attached from the store).
	e2 := jdp_read(j, 2)
	addr := jrn_entry_attr(e2, 'payload')
	assert addr.starts_with('sha2-256:'), 'payload attr must be a tagged address, got `${addr}`'
	assert jrn_entry_event(e2) is cx.Element, 'read must hydrate the event'

	// SHRED: destroy entry 2's payload doc. The chain must STILL verify —
	// the preimage covers the address, which is intact (the L184 mandate).
	del := journal_shred_payload_for_test(j, addr)
	assert del, 'payload doc must delete'
	assert jdp_verify_valid(j), 'verify must stay GREEN with the payload destroyed'

	// The shredded entry reads event-less; its siblings still hydrate.
	e2b := jdp_read(j, 2)
	assert !(jrn_entry_event(e2b) is cx.Element), 'shredded entry must read event-less'
	e3 := jdp_read(j, 3)
	assert jrn_entry_event(e3) is cx.Element, 'sibling entries still hydrate'
}

fn test_payload_address_is_covered_by_the_hash() {
	// Two identical envelopes differing ONLY in payload address must
	// produce different canonical bytes (and so different hashes) — the
	// address-integrity half of the mandate.
	a := jrn_canonical_bytes(1, 'acme', '', 'did:key:test', 'test:suite',
		'1970-01-01T00:00:01Z', 'genesis:', 'sha2-256:' + 'aa'.repeat(32))
	b := jrn_canonical_bytes(1, 'acme', '', 'did:key:test', 'test:suite',
		'1970-01-01T00:00:01Z', 'genesis:', 'sha2-256:' + 'bb'.repeat(32))
	assert a != b
}

// ── source: vcx/platform/journal_head_fresh_test.v ──
// journal_head_fresh_test.v — stream 7 F1 (#679 / #714 item 1): the
// stale-`head` / `head-fresh` discriminator pair over a REAL file substrate.
//
// The supported cross-process shape is ONE writer + N read-only readers on a
// local root; a read-only open takes a PRIVATE SNAPSHOT view
// (store_open_shared_or_conflict), so the writer's later appends are
// invisible to it. This test pins BOTH halves of the ruled F1 resolution:
//   1. `head` on the read-only handle answers the CACHED view — a stale
//      position, with no signal (the STATED contract, journal.md §3.3/§4.6:
//      head makes no freshness claim — this assertion documents the
//      degradation instead of letting it hide);
//   2. `head-fresh` re-takes the view from the durable substrate through
//      the normal capability-gated open path and answers the true head.
// Plus the W3 advert repair: a bare file:// journal resolves to the cxpack
// backend (subtree default), which is a LOCAL mount — it must accept a
// declared `:read-your-writes` floor (the W2 list said mem/file only).

fn jhf_str(s string) cx.Node {
	return cx.ScalarNode{
		value:     cx.ScalarValue(s)
		data_type: cx.ScalarType.string_type
	}
}

fn jhf_map(pairs map[string]string) cx.Node {
	mut items := []cx.Node{}
	for k, v in pairs {
		items << cx.Node(cx.Element{
			name:  k
			items: [cx.Node(jhf_str(v))]
		})
	}
	return cx.Element{
		name:  code.map_marker_name
		items: items
	}
}

fn jhf_attribution() cx.Node {
	return jhf_map({
		'actor':     'writer-1'
		'authority': 'test:suite'
	})
}

fn jhf_seq_of(n cx.Node) int {
	if n is cx.Element {
		return jrn_entry_attr(n, 'seq').int()
	}
	return -1
}

fn test_head_fresh_file_stale_pair() {
	caps_set_all()
	root := os.join_path(os.temp_dir(), 'cx-jhf-${os.getpid()}')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	url := 'file://${root}'

	// Writer opens the root and commits entry 1 (durable at return — #614
	// group-commit scopes close per verb).
	w := journal_stdlib_builtin('journal-open', [jhf_str(url), jhf_str('acme')]) or {
		panic('writer open failed')
	}
	e1 := journal_stdlib_builtin('journal-append', [w, cx.Node(cx.Element{ name: 'a' }),
		jhf_attribution()]) or { panic('append e1 failed') }
	assert jhf_seq_of(e1) == 1

	// Read-only sibling opens the SAME root — a private snapshot view at
	// position 1.
	r := journal_stdlib_builtin('journal-open', [jhf_str(url), jhf_str('acme'),
		jhf_map({
		'read-only': 'true'
	})]) or { panic('read-only open failed') }

	// The writer advances the durable chain past the reader's snapshot.
	e2 := journal_stdlib_builtin('journal-append', [w, cx.Node(cx.Element{ name: 'b' }),
		jhf_attribution()]) or { panic('append e2 failed') }
	assert jhf_seq_of(e2) == 2

	// F1, half 1 — the STATED degradation: `head` answers the reader's
	// cached view (seq 1), a stale position with no signal.
	stale := journal_stdlib_builtin('journal-head', [r]) or { panic('head failed') }
	assert jhf_seq_of(stale) == 1, 'head must answer the cached view (stale seq 1), got ${jhf_seq_of(stale)}'

	// F1, half 2 — the declared-fresh verb: `head-fresh` re-takes the view
	// from the substrate and answers the true head (seq 2).
	fresh := journal_stdlib_builtin('journal-head-fresh', [r]) or { panic('head-fresh failed') }
	assert jhf_seq_of(fresh) == 2, 'head-fresh must answer the durable head (seq 2), got ${jhf_seq_of(fresh)}'

	// And the refreshed view SERVES the new entry (read-through + view swap):
	got := journal_stdlib_builtin('journal-read', [r, cx.Node(cx.ScalarNode{
		value:     cx.ScalarValue(i64(2))
		data_type: cx.ScalarType.int_type
	})]) or { panic('read 2 failed') }
	assert jhf_seq_of(got) == 2

	journal_stdlib_builtin('journal-close', [r]) or { cx.Node(cx.Element{ name: 'x' }) }
	journal_stdlib_builtin('journal-close', [w]) or { cx.Node(cx.Element{ name: 'x' }) }
}

fn test_cxpack_backed_journal_advertises_read_your_writes() {
	caps_set_all()
	root := os.join_path(os.temp_dir(), 'cx-jhf-rw-${os.getpid()}')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	// A bare file:// journal store resolves to the cxpack backend (subtree
	// default) — a local mount, so a declared :read-your-writes floor is
	// SATISFIABLE and must be accepted (the W2 advert listed mem/file only —
	// an over-refusal on the real file substrate).
	consistency := cx.Element{
		name:  'consistency'
		items: [
			cx.Node(cx.ScalarNode{
				value:     cx.ScalarValue('read-your-writes')
				data_type: cx.ScalarType.atom_type
			}),
		]
	}
	opts := cx.Element{
		name:  code.map_marker_name
		items: [cx.Node(consistency)]
	}
	j := journal_stdlib_builtin('journal-open', [jhf_str('file://${root}'), jhf_str('acme'),
		cx.Node(opts)]) or { panic('open failed') }
	je := j as cx.Element
	assert je.name == 'journal', 'expected an accepted open, got ${je.name}'
	assert jrn_entry_attr(je, 'consistency') == ':read-your-writes'
	journal_stdlib_builtin('journal-close', [j]) or { cx.Node(cx.Element{ name: 'x' }) }
}

// ── source: vcx/platform/journal_remote_wire_test.v ──
// journal_remote_wire_test.v — #644: the journal rides a cx-store:// mount.
//
// A journal ATTACHED to a CSRP client handle appends, re-reads, verifies, and
// reloads entirely over the object wire: entry docs travel as objects
// (put-doc), the per-stream head/algo metadata and entry pointers ride the
// #645 alias remoting (`aliases` / `aliases-set`) into the DAEMON's
// authoritative tables — so a second attach (a fresh journal instance, or a
// different process) rehydrates the chain from the daemon and the hash chain
// verifies green. Exercised HERMETICALLY through store_csrp_route (no socket),
// like store_cxstore_wire_test.v.

struct JrwLoopback {
	daemon cx.Node
}

fn (t &JrwLoopback) send(op string, query string, body string) (int, string, bool) {
	mut qp := map[string]string{}
	if query != '' {
		for part in query.split('&') {
			kv := part.split('=')
			if kv.len == 2 {
				qp[kv[0]] = kv[1]
			}
		}
	}
	resp := svc_profile_data_op(grpc_synth_req(op, '', body, qp, '', ''), t.daemon, op)
	mut status := 0
	if resp is cx.Element {
		status = sw_attr(resp, 'status').int()
	}
	return status, svc_response_body(resp), true
}

fn jrw_client(daemon cx.Node, tag string) cx.Node {
	rb, _, _ := store_remote_parse('cx-store+xsp://loopback:1/${tag}/')
	mut ms := &MemStore{
		url:         'cx-store+xsp://loopback:1/${tag}/'
		backend:     'cx-store'
		encoding:    'cxbin'
		compression: 'none'
		is_open:     true
		op_lock:     sync.new_mutex()
		remote:      rb
		obj_backend: cxstore.ObjectBackend(&RemoteObjectBackend{
			transport: ObjWireTransport(&JrwLoopback{
				daemon: daemon
			})
		})
	}
	id := store_register(ms)
	return store_handle_element(id, ms)
}

fn jrw_append(j cx.Node, event string) cx.Node {
	ev := cx.parse(event) or { panic('parse event') }.elements[0]
	attribution := cx.Element{
		name:  code.map_marker_name
		items: [
			cx.Node(cx.Element{
				name:  'actor'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('did:key:test')
					data_type: cx.ScalarType.string_type
				})]
			}),
			cx.Node(cx.Element{
				name:  'authority'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('test:suite')
					data_type: cx.ScalarType.string_type
				})]
			}),
		]
	}
	return journal_stdlib_builtin('journal-append', [j, cx.Node(ev), cx.Node(attribution)]) or {
		panic('append: ${err.msg()}')
	}
}

fn test_journal_attach_on_csrp_client_appends_and_reloads() {
	caps_set_all() // remote store ops are net effects; grant like the daemon process does
	daemon := store_open_impl('mem://jrw-daemon', '', '', false, true, map[string]string{})
	client := jrw_client(daemon, 'j')

	// attach a journal to the REMOTE handle and append two events.
	j := journal_stdlib_builtin('journal-attach', [client, store_str('acme')]) or {
		panic('attach: ${err.msg()}')
	}
	assert !is_err_value(j), 'attach on a CSRP client handle must succeed: ${render_canonical(j)}'
	r1 := jrw_append(j, '[do :a]')
	assert !is_err_value(r1), 'append 1 over the wire: ${render_canonical(r1)}'
	r2 := jrw_append(j, '[do :b]')
	assert !is_err_value(r2), 'append 2 over the wire: ${render_canonical(r2)}'

	// the chain head advanced on the DAEMON's authoritative tables.
	hd := journal_stdlib_builtin('journal-head', [j]) or { panic('head: ${err.msg()}') }
	assert render_canonical(hd).contains('seq=2'), 'head must be seq 2: ${render_canonical(hd)}'

	// verify green over the wire.
	v := journal_stdlib_builtin('journal-verify', [j]) or { panic('verify: ${err.msg()}') }
	assert !is_err_value(v), 'verify: ${render_canonical(v)}'
	assert render_canonical(v).contains('valid=true'), 'chain must verify: ${render_canonical(v)}'

	// a FRESH attach (second client instance — the reopen path) rehydrates the
	// chain from the daemon: head, entries, and verification all green.
	client2 := jrw_client(daemon, 'j2')
	j2 := journal_stdlib_builtin('journal-attach', [client2, store_str('acme')]) or {
		panic('re-attach: ${err.msg()}')
	}
	assert !is_err_value(j2), 're-attach: ${render_canonical(j2)}'
	hd2 := journal_stdlib_builtin('journal-head', [j2]) or { panic('head2: ${err.msg()}') }
	assert render_canonical(hd2).contains('seq=2'), 'rehydrated head must be seq 2: ${render_canonical(hd2)}'
	rd := journal_stdlib_builtin('journal-read', [j2, cx.Node(bus_int(1))]) or {
		panic('read: ${err.msg()}')
	}
	assert render_canonical(rd).contains(':a'), 'entry 1 must rehydrate: ${render_canonical(rd)}'
	v2 := journal_stdlib_builtin('journal-verify', [j2]) or { panic('verify2: ${err.msg()}') }
	assert render_canonical(v2).contains('valid=true'), 'rehydrated chain must verify: ${render_canonical(v2)}'

	// a third append CONTINUES the chain from the rehydrated head.
	r3 := jrw_append(j2, '[do :c]')
	assert !is_err_value(r3), 'append 3 after rehydrate: ${render_canonical(r3)}'
	assert render_canonical(r3).contains('seq=3'), 'chain continues at seq 3: ${render_canonical(r3)}'
}

// ── source: vcx/platform/journal_rotate_test.v ──
// journal_rotate_test.v — #640: `journal-rotate` seals the live chain at a
// retention boundary and moves the hot window to a fresh store (snapshot →
// retain → compact composed), leaving a walkable SEGMENT INDEX in the new
// store. Rotation is copy-then-swap: the source is never mutated, the
// returned journal is the new hot, and a chain of rotations stays
// discoverable from the newest store alone.

const jrt_seed = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

fn jrt_append(j cx.Node, event string) cx.Node {
	ev := cx.parse(event) or { panic('parse event') }.elements[0]
	attribution := cx.Element{
		name:  code.map_marker_name
		items: [
			cx.Node(cx.Element{
				name:  'actor'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('did:key:test')
					data_type: cx.ScalarType.string_type
				})]
			}),
			cx.Node(cx.Element{
				name:  'authority'
				items: [cx.Node(cx.ScalarNode{
					value:     cx.ScalarValue('test:suite')
					data_type: cx.ScalarType.string_type
				})]
			}),
		]
	}
	r := journal_stdlib_builtin('journal-append', [j, cx.Node(ev), cx.Node(attribution)]) or {
		panic('append: ${err.msg()}')
	}
	assert !is_err_value(r), 'append must succeed: ${render_canonical(r)}'
	return r
}

fn jrt_rotate(j cx.Node, keep_n int, target string) cx.Node {
	r := journal_stdlib_builtin('journal-rotate', [j, cx.Node(cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('keep-n', bus_int(keep_n)),
			session_kv('target', bus_str(target)),
			session_kv('signing-key', bus_str(jrt_seed)),
		]
	})]) or { panic('rotate: ${err.msg()}') }
	return r
}

fn test_journal_rotate_seals_and_moves_the_hot_window() {
	caps_set_all()
	j := journal_stdlib_builtin('journal-open', [store_str('mem://jrt-src'), store_str('acme')]) or {
		panic('open')
	}
	for i in 1 .. 6 {
		jrt_append(j, '[do :e${i}]')
	}

	// rotate keeping the last 2 → boundary 3, one sealed segment recorded.
	r := jrt_rotate(j, 2, 'mem://jrt-hot2')
	assert !is_err_value(r), 'rotate: ${render_canonical(r)}'
	rr := r as cx.Element
	assert rr.name == 'rotated', 'rotate returns [rotated …]: ${render_canonical(r)}'
	assert rr.attr('sealed') == '1' && rr.attr('streams') == '1', 'one stream sealed: ${render_canonical(r)}'
	assert rr.attr('segments') == '1', 'first rotation records ONE sealed segment: ${render_canonical(r)}'
	mut hot := cx.Node(cx.Element{})
	for it in rr.items {
		if it is cx.Element && it.name == 'journal' {
			hot = it
		}
	}

	// the new hot journal: seam at 3, head 5; the retained tail reads; the
	// sealed range is honestly out of range; the chain verifies from the seam.
	hd := journal_stdlib_builtin('journal-head', [hot]) or { panic('head') }
	assert render_canonical(hd).contains('seq=5'), 'hot head: ${render_canonical(hd)}'
	e4 := journal_stdlib_builtin('journal-read', [hot, cx.Node(bus_int(4))]) or { panic('read4') }
	assert render_canonical(e4).contains(':e4'), 'retained entry must read: ${render_canonical(e4)}'
	e2 := journal_stdlib_builtin('journal-read', [hot, cx.Node(bus_int(2))]) or { panic('read2') }
	assert !render_canonical(e2).contains(':e2'), 'a sealed seq must not read from the hot window: ${render_canonical(e2)}'
	v := journal_stdlib_builtin('journal-verify', [hot]) or { panic('verify') }
	assert render_canonical(v).contains('valid=true'), 'seam-anchored verify: ${render_canonical(v)}'

	// the SOURCE journal is untouched (copy-then-swap).
	sv := journal_stdlib_builtin('journal-verify', [j]) or { panic('src verify') }
	assert render_canonical(sv).contains('valid=true'), 'source stays intact: ${render_canonical(sv)}'
	shd := journal_stdlib_builtin('journal-head', [j]) or { panic('src head') }
	assert render_canonical(shd).contains('seq=5'), 'source head unchanged'

	// the chain CONTINUES on the new hot journal.
	r6 := jrt_append(hot, '[do :e6]')
	assert render_canonical(r6).contains('seq=6'), 'chain continues at 6: ${render_canonical(r6)}'

	// second rotation: the segment index carries the first segment forward.
	r2 := jrt_rotate(hot, 1, 'mem://jrt-hot3')
	assert !is_err_value(r2), 'rotate 2: ${render_canonical(r2)}'
	rr2 := r2 as cx.Element
	assert rr2.attr('sealed') == '1', 'second rotation seals again: ${render_canonical(r2)}'
	assert rr2.attr('segments') == '2', 'the index chains BOTH sealed segments: ${render_canonical(r2)}'
	mut hot3 := cx.Node(cx.Element{})
	for it in rr2.items {
		if it is cx.Element && it.name == 'journal' {
			hot3 = it
		}
	}
	v3 := journal_stdlib_builtin('journal-verify', [hot3]) or { panic('verify3') }
	assert render_canonical(v3).contains('valid=true'), 'second seam verifies: ${render_canonical(v3)}'
	e6 := journal_stdlib_builtin('journal-read', [hot3, cx.Node(bus_int(6))]) or { panic('read6') }
	assert render_canonical(e6).contains(':e6'), 'newest hot retains the tail: ${render_canonical(e6)}'
}

fn test_journal_rotate_refuses_without_cover_or_boundary() {
	caps_set_all()
	j := journal_stdlib_builtin('journal-open', [store_str('mem://jrt-ref'), store_str('acme')]) or {
		panic('open')
	}
	jrt_append(j, '[do :a]')
	jrt_append(j, '[do :b]')
	// no signing key and no snapshot → the §4.9 contract refuses.
	r := journal_stdlib_builtin('journal-rotate', [j, cx.Node(cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('keep-n', bus_int(1)),
			session_kv('target', bus_str('mem://jrt-ref2')),
		]
	})]) or { panic('rotate dispatch') }
	assert is_err_value(r), 'unsigned rotation must refuse'
	assert err_code_of(r) == 'cx-err:CXER4614', 'refusal is E_JOURNAL_SNAPSHOT_UNSIGNED: ${render_canonical(r)}'
	// a boundary that seals nothing refuses (keep-n >= head).
	r2 := journal_stdlib_builtin('journal-rotate', [j, cx.Node(cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('keep-n', bus_int(5)),
			session_kv('target', bus_str('mem://jrt-ref3')),
			session_kv('signing-key', bus_str(jrt_seed)),
		]
	})]) or { panic('rotate dispatch 2') }
	assert is_err_value(r2), 'a nothing-to-seal rotation must refuse'
}

// streams=all — the fabric mount-swap mode: every stream moves at its OWN
// boundary; a stream whose boundary floors at 0 is copied whole (nothing
// sealed for it, no index entry) so NOTHING vanishes from the hot window.
fn test_journal_rotate_all_streams() {
	caps_set_all()
	j := journal_stdlib_builtin('journal-open', [store_str('mem://jrt-all'), store_str('acme')]) or {
		panic('open')
	}
	// three entries on stream a, one on stream b (via the attribution map).
	for i in 1 .. 4 {
		ev := cx.parse('[do :a${i}]') or { panic('p') }.elements[0]
		attribution := cx.Element{
			name:  code.map_marker_name
			items: [
				session_kv('actor', bus_str('did:key:test')),
				session_kv('authority', bus_str('test:suite')),
				session_kv('stream', bus_str('a')),
			]
		}
		r := journal_stdlib_builtin('journal-append', [j, cx.Node(ev), cx.Node(attribution)]) or {
			panic('append a')
		}
		assert !is_err_value(r), 'append a${i}: ${render_canonical(r)}'
	}
	evb := cx.parse('[do :b1]') or { panic('p') }.elements[0]
	battr := cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('actor', bus_str('did:key:test')),
			session_kv('authority', bus_str('test:suite')),
			session_kv('stream', bus_str('b')),
		]
	}
	rb := journal_stdlib_builtin('journal-append', [j, cx.Node(evb), cx.Node(battr)]) or {
		panic('append b')
	}
	assert !is_err_value(rb), 'append b1: ${render_canonical(rb)}'

	r := journal_stdlib_builtin('journal-rotate', [j, cx.Node(cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('streams', bus_str('all')),
			session_kv('keep-n', bus_int(1)),
			session_kv('target', bus_str('mem://jrt-all2')),
			session_kv('signing-key', bus_str(jrt_seed)),
		]
	})]) or { panic('rotate all') }
	assert !is_err_value(r), 'rotate all: ${render_canonical(r)}'
	rr := r as cx.Element
	assert rr.attr('streams') == '2', 'both streams move: ${render_canonical(r)}'
	assert rr.attr('sealed') == '1', 'only stream a seals (b floors at 0): ${render_canonical(r)}'
	mut hot := cx.Node(cx.Element{})
	for it in rr.items {
		if it is cx.Element && it.name == 'journal' {
			hot = it
		}
	}
	// stream a: seam at 2, head 3; stream b: copied whole.
	ha := journal_stdlib_builtin('journal-head', [hot, cx.Node(bus_str('a'))]) or { panic('ha') }
	assert render_canonical(ha).contains('seq=3'), 'a head: ${render_canonical(ha)}'
	hb := journal_stdlib_builtin('journal-head', [hot, cx.Node(bus_str('b'))]) or { panic('hb') }
	assert render_canonical(hb).contains('seq=1'), 'b head: ${render_canonical(hb)}'
	sb := journal_stdlib_builtin('journal-since', [hot, cx.Node(bus_int(0)), cx.Node(bus_str('b'))]) or {
		panic('since b')
	}
	assert render_canonical(sb).contains(':b1'), 'b copied whole: ${render_canonical(sb)}'
}

// ── source: vcx/platform/journal_ts_form_test.v ──
// I1 row 10 (#712 / bitemporal L116 / stream-12 ruling 20): the journal's
// DEFAULT synthetic ts is a real ISO-8601 UTC-Z instant — the Unix epoch
// plus seq seconds — deterministic, capability-free, monotonic, and
// spec-conformant in FORM (the pre-I1 `epoch:HH:MM:SS` spelling was not a
// datetime and silently wrapped at 24h; day boundaries now roll the DATE).
// These are the ts-form vectors #712 requires ahead of the journal-class
// re-bless. Real wall-clock ts remains the opts.clock opt-in.

fn empty_opts() cx.Node {
	return cx.Node(cx.Element{ name: 'opts' })
}

fn test_ts_form_vectors() {
	vectors := {
		0:     '1970-01-01T00:00:00Z'
		1:     '1970-01-01T00:00:01Z'
		61:    '1970-01-01T00:01:01Z'
		3661:  '1970-01-01T01:01:01Z'
		86399: '1970-01-01T23:59:59Z'
		86400: '1970-01-02T00:00:00Z' // the day ROLLS — the old form wrapped here
		90061: '1970-01-02T01:01:01Z'
	}
	for seq, want in vectors {
		got := jrn_ts_for(empty_opts(), seq)
		assert got == want, 'seq ${seq}: got ${got}, want ${want}'
	}
}

fn test_ts_is_a_datetime_and_monotonic() {
	mut prev := ''
	for seq in [0, 1, 59, 60, 86399, 86400, 100000] {
		ts := jrn_ts_for(empty_opts(), seq)
		// The spelling must READ as a datetime scalar (UTC-Z instant) —
		// the #712 defect was exactly a non-datetime ts. Body auto-type
		// ([L25a]) is the reference reader.
		doc := cx.parse('[e ${ts}]') or {
			assert false, 'seq ${seq} ts ${ts} failed to parse: ${err}'
			return
		}
		el := doc.elements[0]
		if el is cx.Element {
			assert el.items.len == 1
			body := el.items[0]
			assert body is cx.ScalarNode, 'seq ${seq}: ${ts} did not auto-type'
			if body is cx.ScalarNode {
				assert body.data_type == cx.ScalarType.datetime_type,
					'seq ${seq}: ${ts} did not read as a datetime'
			}
		}
		assert ts > prev || prev == '', 'seq ${seq}: not monotonic (${prev} → ${ts})'
		prev = ts
	}
}

fn test_clock_opt_in_still_wins() {
	mut opts := cx.Element{ name: 'opts' }
	opts.attrs = [cx.new_attribute('clock', cx.ScalarValue('2026-08-05T12:00:00Z'),
		cx.AttributeMeta{})]
	got := jrn_ts_for(cx.Node(opts), 7)
	assert got == '2026-08-05T12:00:00Z'
}

// ── #785: the DERIVED open inherits the source's posture ──
// journal_rotate/compact open their TARGET through the ordinary journal open
// path. Opening it bare made the target PLAINTEXT even when the source sealed
// at rest — so an encrypted journal could not rotate at all, and a rotation of
// an encrypted chain silently DOWNGRADED the at-rest posture at every segment
// boundary. Found at the same call site: the target also took the DEFAULT
// hash-algo, stamping `sha2-256` on a segment whose copied-verbatim entries
// were hashed under the source's algo — a segment that fails its own verify.

const jar_kek = '00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff'

fn jar_open(url string, tenant string, opts map[string]string) cx.Node {
	mut items := []cx.Node{}
	for k, v in opts {
		items << session_kv(k, bus_str(v))
	}
	return journal_stdlib_builtin('journal-open', [store_str(url), store_str(tenant),
		cx.Node(cx.Element{
			name:  code.map_marker_name
			items: items
		})]) or { panic('open ${url}: ${err.msg()}') }
}

// jar_store_of answers the backing store record of an open journal handle —
// the at-rest posture under test is a property of THAT store, not of the
// journal's own bookkeeping.
fn jar_store_of(j cx.Node) &MemStore {
	mut jj, _, ok := jrn_get_open(j)
	assert ok, 'handle must be an open journal'
	return store_lookup(jj.store_id) or { panic('backing store gone') }
}

fn jar_hot_of(rotated cx.Node) cx.Node {
	rr := rotated as cx.Element
	for it in rr.items {
		if it is cx.Element && it.name == 'journal' {
			return it
		}
	}
	panic('rotate returned no [journal …]: ${render_canonical(rotated)}')
}

fn test_rotate_target_inherits_encryption_at_rest() {
	caps_set_all()
	os.setenv('CX_STORE_KEK_jar_a', jar_kek, true)
	src := os.join_path(os.temp_dir(), 'cx_jar_src_${os.getpid()}')
	dst := os.join_path(os.temp_dir(), 'cx_jar_hot_${os.getpid()}')
	os.rmdir_all(src) or {}
	os.rmdir_all(dst) or {}
	defer {
		os.rmdir_all(src) or {}
		os.rmdir_all(dst) or {}
		os.unsetenv('CX_STORE_KEK_jar_a')
	}

	// `journal-open` speaks the at-rest keys itself (#785): sealing a chain no
	// longer requires the store-open-then-attach detour.
	j := jar_open('file://${src}', 'acme', {
		'encrypt-key-id': 'jar_a'
	})
	assert !is_err_value(j), 'encrypted open: ${render_canonical(j)}'
	assert jar_store_of(j).enc_key_id == 'jar_a', 'the journal-open key must reach the store'
	for i in 1 .. 6 {
		jrt_append(j, '[do :e${i}]')
	}

	r := jrt_rotate(j, 2, 'file://${dst}')
	assert !is_err_value(r), 'an encrypted journal must rotate: ${render_canonical(r)}'
	hot := jar_hot_of(r)

	// THE DEFECT: without inheritance the fresh target opens plaintext — the
	// at-rest posture is lost at the rotation boundary.
	assert jar_store_of(hot).enc_key_id == 'jar_a', 'the rotated hot store must stay sealed at rest'

	// and it is a working chain: the retained tail reads, the seam verifies.
	e4 := journal_stdlib_builtin('journal-read', [hot, cx.Node(bus_int(4))]) or { panic('read4') }
	assert render_canonical(e4).contains(':e4'), 'retained entry reads: ${render_canonical(e4)}'
	v := journal_stdlib_builtin('journal-verify', [hot]) or { panic('verify') }
	assert render_canonical(v).contains('valid=true'), 'sealed segment verifies: ${render_canonical(v)}'

	// REOPENING an existing encrypted store as the next target works too (the
	// self-describing reopen needs the key, which now travels).
	journal_stdlib_builtin('journal-close', [hot]) or { panic('close') }
	re := jar_open('file://${dst}', 'acme', {
		'encrypt-key-id': 'jar_a'
	})
	assert !is_err_value(re), 'encrypted reopen: ${render_canonical(re)}'
	e5 := journal_stdlib_builtin('journal-read', [re, cx.Node(bus_int(5))]) or { panic('read5') }
	assert render_canonical(e5).contains(':e5'), 'the sealed bytes read back: ${render_canonical(e5)}'
}

// An EXPLICIT key on the rotate opts overrides the inheritance — the
// key-per-segment policy (each new hot window under its own KEK).
fn test_rotate_opts_key_overrides_the_inherited_one() {
	caps_set_all()
	os.setenv('CX_STORE_KEK_jar_a', jar_kek, true)
	os.setenv('CX_STORE_KEK_jar_b', 'ffeeddccbbaa99887766554433221100ffeeddccbbaa99887766554433221100',
		true)
	src := os.join_path(os.temp_dir(), 'cx_jar_ov_src_${os.getpid()}')
	dst := os.join_path(os.temp_dir(), 'cx_jar_ov_hot_${os.getpid()}')
	os.rmdir_all(src) or {}
	os.rmdir_all(dst) or {}
	defer {
		os.rmdir_all(src) or {}
		os.rmdir_all(dst) or {}
		os.unsetenv('CX_STORE_KEK_jar_a')
		os.unsetenv('CX_STORE_KEK_jar_b')
	}
	j := jar_open('file://${src}', 'acme', {
		'encrypt-key-id': 'jar_a'
	})
	for i in 1 .. 5 {
		jrt_append(j, '[do :o${i}]')
	}
	r := journal_stdlib_builtin('journal-rotate', [j, cx.Node(cx.Element{
		name:  code.map_marker_name
		items: [
			session_kv('keep-n', bus_int(2)),
			session_kv('target', bus_str('file://${dst}')),
			session_kv('signing-key', bus_str(jrt_seed)),
			session_kv('encrypt-key-id', bus_str('jar_b')),
		]
	})]) or { panic('rotate: ${err.msg()}') }
	assert !is_err_value(r), 'rotate under a new KEK: ${render_canonical(r)}'
	hot := jar_hot_of(r)
	assert jar_store_of(hot).enc_key_id == 'jar_b', 'the explicit opts key must win over the inherited one'
	v := journal_stdlib_builtin('journal-verify', [hot]) or { panic('verify') }
	assert render_canonical(v).contains('valid=true'), 'the re-keyed segment verifies: ${render_canonical(v)}'
}

// The same call site dropped the source's HASH-ALGO: the target was stamped
// `sha2-256` while carrying entries hashed under the source's algo, so the
// segment failed its own verify.
fn test_rotate_target_inherits_hash_algo() {
	caps_set_all()
	j := jar_open('mem://jar-b3-src', 'acme', {
		'hash-algo': 'blake3'
	})
	assert !is_err_value(j), 'blake3 open: ${render_canonical(j)}'
	for i in 1 .. 6 {
		jrt_append(j, '[do :b${i}]')
	}
	r := jrt_rotate(j, 2, 'mem://jar-b3-hot')
	assert !is_err_value(r), 'blake3 rotate: ${render_canonical(r)}'
	hot := jar_hot_of(r)
	mut hj, _, ok := jrn_get_open(hot)
	assert ok
	assert hj.hash_algo == 'blake3', 'the segment must carry the source algo, got ${hj.hash_algo}'
	v := journal_stdlib_builtin('journal-verify', [hot]) or { panic('verify') }
	assert render_canonical(v).contains('valid=true'), 'a blake3 segment verifies under its own algo: ${render_canonical(v)}'
	// the chain continues on the segment under the SAME algo.
	r6 := jrt_append(hot, '[do :b6]')
	assert render_canonical(r6).contains('seq=6'), 'chain continues: ${render_canonical(r6)}'
	v2 := journal_stdlib_builtin('journal-verify', [hot]) or { panic('verify2') }
	assert render_canonical(v2).contains('valid=true'), 'and stays verifiable: ${render_canonical(v2)}'
}
